function parseArgs(){let e,a,s,r,t,c;const i=[],o=process.argv.slice(2);for(let n=0;n<o.length;n++){const l=o[n];switch(l){case"--convert":case"-c":e=!0;break;case"--space":case"-s":a=o[++n];break;case"--validate":case"-v":s=!0;break;case"--out-file":case"-o":r=o[++n];break;case"--version":case"-V":t=!0;break;case"--help":case"-h":c=!0;break;default:i.push(l)}}return{convert:e,space:a,validate:s,outFile:r,version:t,help:c,defaults:i}}function version(){}function usage(){}const fs=require("fs"),path=require("path"),pkg=require("../package.json"),JSON5=require("./"),argv=parseArgs();if(argv.version)version();else if(argv.help)usage();else{const e=argv.defaults[0];let a;a=e?fs.createReadStream(e):process.stdin;let s="";a.on("data",(e=>{s+=e})),a.on("end",(()=>{let a,r;a="t"===argv.space||"tab"===argv.space?"\t":Number(argv.space);try{if(r=JSON5.parse(s),!argv.validate){const s=JSON.stringify(r,null,a);let t;if(argv.convert&&e&&!argv.outFile){const a=path.parse(e),s=path.format(Object.assign(a,{base:path.basename(a.base,a.ext)+".json"}));t=fs.createWriteStream(s)}else t=argv.outFile?fs.createWriteStream(argv.outFile):process.stdout;t.write(s)}}catch(e){process.exit(1)}}))}